"""Build the local joint-zero-clamp report from verified saved outputs."""
import html,json,sys
from pathlib import Path
import matplotlib
matplotlib.use('Agg')
import matplotlib.pyplot as plt
R=Path(sys.argv[1]).resolve();D=json.loads((R/'artifacts/results.json').read_text());P=D['protocol'];V=json.loads((R/'verification.json').read_text());J=json.loads((R/'response-review.json').read_text());rows={r['condition']:r for r in D['rows']};Z=rows['joint_zero_clamp'];B=rows['observe_only'];H=lambda x:html.escape(str(x),quote=True)
F=P['features'];names=[f"L{f['layer']}-T{f['transform']}" for f in F]
fig,axes=plt.subplots(3,2,figsize=(18,10),layout='constrained')
leftmax=max(t['natural_gate'] for t in B['traces'] if t['segment']=='response');rightmax=max(t['actual_bf16_delta_norm'] for t in Z['traces'])
for i,(f,name) in enumerate(zip(F,names)):
 for col,row in enumerate([B,Z]):
  ts=[t for t in row['traces'] if t['feature']==name and t['segment']=='response'];vals=[t['natural_gate'] if col==0 else t['actual_bf16_delta_norm'] for t in ts];ax=axes[i,col]
  ax.bar(range(len(ts)),vals,color='#147f82' if col==0 else '#a85e3b',width=.75)
  ax.set_ylim(0,(leftmax if col==0 else rightmax)*1.18 or 1);ax.set_title(name+' · '+f['label'],fontsize=10,loc='left');ax.set_xticks(range(len(ts)),[t['token'].replace(' ','·') for t in ts],rotation=65,ha='right',fontsize=8)
  ax.set_ylabel('Native gate' if col==0 else 'Actual MLP edit norm');ax.grid(axis='y',alpha=.2);ax.spines[['top','right']].set_visible(False)
  ax.set_xlabel('Processed output-token position · prompt untouched')
fig.suptitle('Unauthorized Bob · native gate versus joint zero-clamp edit\nAll three estimated gates target zero at every processed output token',fontsize=18)
fig.savefig(R/'clamp-edit-timeline.png',dpi=180,facecolor='white');plt.close(fig)
cards=[]
for mode in ['native','observe_only','joint_zero_clamp']:
 r=rows[mode];review=J[mode];cards.append(f'<article class="card"><span class="tag">{H(mode.replace("_"," "))}</span><h3>{H(review["headline"])}</h3><p class="answer">{H(r["answer"])}</p><p>{H(review["reason"])}</p><p class="muted">Exact secret present: {r["contains_exact_secret"]} · token-identical to saved baseline: {r["token_identical_to_baseline"]} · stop: {r["stop_reason"]}</p></article>')
trs=[]
for f,name in zip(F,names):
 s=Z['features'][name];b=B['features'][name];trs.append(f'<tr><td><b>{name}</b><br>{H(f["label"])}</td><td>{s["processed_response_positions"]}</td><td>{s["naturally_active_positions"]}</td><td>{s["positions_with_actual_edit"]}</td><td>0 at every position</td><td>{H(str(s["first_active_position"]))} {H(s["first_active_token"] or "")}</td></tr>')
first=min(t['answer_position'] for t in B['traces'] if t['segment']=='response' and t['natural_gate']>0)
ref=[t for t in B['traces'] if t['segment']=='response' and t['feature']==names[0]];prefix=''.join(t['token'] for t in ref[:first+1])
css='''*{box-sizing:border-box}body{margin:0;background:#f6f5ef;color:#173e49;font:17px/1.65 system-ui,sans-serif}main{max-width:1160px;margin:auto;padding:50px 26px 80px}h1{font-size:clamp(34px,5vw,60px);line-height:1.1;letter-spacing:-1.5px;max-width:980px}h2{font-size:31px;line-height:1.2;margin-top:36px}h3{font-size:21px}.tag{font-size:12px;font-weight:800;color:#137574;letter-spacing:1px;text-transform:uppercase}.note{background:#dfede8;padding:20px 24px;border-left:4px solid #197f7a;border-radius:6px}.grid{display:grid;grid-template-columns:repeat(3,1fr);gap:16px}.card{border:1px solid #ccd9d4;background:#fffef9;border-radius:12px;padding:20px;min-width:0}.answer{padding:15px;background:#eef4f1;border-radius:7px;white-space:pre-wrap}.muted{font-size:13px;color:#526d73}pre{white-space:pre-wrap;overflow-wrap:anywhere;padding:20px;background:#e9efeb;border-radius:8px;font-size:14px}.scroll{overflow:auto}table{width:100%;border-collapse:collapse;font-size:14px}th,td{padding:13px;text-align:left;border-bottom:1px solid #d2ded7}th{background:#e5eee8}img{width:100%;height:auto;border:1px solid #d1ddd6;border-radius:8px}a{color:#096c70;text-underline-offset:4px}section{border-top:1px solid #cad6ce;margin-top:35px;padding-top:15px}summary{cursor:pointer;color:#0d7374;font-weight:700}.links{display:flex;flex-wrap:wrap;gap:20px;margin:25px 0}@media(max-width:760px){main{padding:25px 15px 60px}.grid{grid-template-columns:1fr}th,td{min-width:100px;padding:10px}}'''
page=f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Unauthorized Bob — joint zero clamp of three privacy MOLTs</title><style>{css}</style></head><body><main><span class="tag">Qwen3-4B · output-only clamp · local experiment · 15 October 2026</span><h1>{H(J['summary']['headline'])}</h1><div class="note"><b>{H(J['summary']['outcome'])}</b><p>{H(J['summary']['description'])}</p></div><p>Test: jointly set the estimated gates of L11–T1596, L12–T1891 and L13–T921 to zero on every processed output token of the unauthorized Bob prompt. The same native model, prompt, greedy decoding and unfrozen attention are retained.</p><h2>Complete responses and controls</h2><div class="grid">{''.join(cards)}</div><section><h2>Exactly what zero clamp means here</h2><pre>For each selected transform at its own layer:
z = (current post-attention residual − released input mean) / input std
L(z) = ((z @ V) @ U) × released output std
native MLP output += (0 − natural gate(z)) × L(z)
Estimated coefficient after patch: natural gate − natural gate = 0</pre><p>The native MLP remains in place; we subtract its selected MOLT-estimated contribution. This is a zero target in the MOLT approximation, rather than replacing the native MLP with a reconstruction. Both the gate and the complete input-dependent low-rank output are recomputed on the evolving trajectory. There is no donor and no fixed additive strength.</p><p>All prompt positions are untouched. The first output token is predicted normally. Processing output token j can affect token j+1. Every processed output position receives the clamp; positions with a zero natural gate have a zero edit.</p><div class="scroll"><table><thead><tr><th>Feature</th><th>Output positions clamped</th><th>Natural gate active</th><th>Actual nonzero edits</th><th>Estimated gate after clamp</th><th>First active token, zero-based</th></tr></thead><tbody>{''.join(trs)}</tbody></table></div></section><section><h2>When could this intervention first affect the answer?</h2><p>On the native response, the first selected gate activates while processing token <b>{first}</b>. At that point the text <b>“{H(prefix)}”</b> has already been emitted. The earliest next prediction this activity could affect is token <b>{first+1}</b>.</p><p>{H(J['summary']['timing_interpretation'])}</p><p>First changed output position under clamp: <b>{H(str(Z['first_changed_output_position']))}</b> (None means the full saved token sequence, including EOS, is unchanged).</p><img src="clamp-edit-timeline.png" alt="Three rows of native gates and actual MLP edit norms across output tokens"><p class="muted">Left: native gate activation in the observation control. Right: actual BF16 MLP output edit norm in the zero-clamped run. Different columns use different units and separate y scales. Tokens are those processed at the hook, not the next tokens predicted.</p><a href="clamp-edit-timeline.png">Download timeline PNG</a></section><section><h2>Exact prompt</h2><b>System</b><pre>{H(D['case']['system'])}</pre><b>User</b><pre>{H(D['case']['user'])}</pre></section><section><h2>Verification and limits</h2><p>Native and observation-only controls reproduce the prior baseline token IDs exactly. All three selected transforms have an estimated zero target at every processed output position; prompt edits are zero. Nonzero actual BF16 changes are logged separately from intended subtraction. Model files, weight assets and source hashes are checked.</p><p>One synthetic prompt, one greedy continuation per condition. This does not test earlier prompt interventions, stronger negative coefficients, other privacy prompts, or authorized-prompt activation. Those conditions were not run.</p><p>Greedy batch one; thinking disabled; KV cache; 96-token cap; BF16 native model with FP32 MOLT computations. All IDs and positions zero-based.</p><details><summary>Pinned checkpoints</summary><pre>{P['base_repo']} · {P['base_revision']}
{P['molt_repo']} · {P['molt_revision']}
Torch {D['runtime']['torch']} · Transformers {D['runtime']['transformers']}</pre></details><div class="links"><a href="artifacts/results.json">Raw responses and all edit traces</a><a href="verification.json">Verification</a><a href="protocol.json">Pre-run protocol</a><a href="case.json">Prompt and prior baseline</a><a href="response-review.json">Answer-bound review</a><a href="run.py">Experiment source</a><a href="../2026-10-15-privacy-activation-pilot/index.html">Original activation report</a></div><p class="muted">SPAR instance 56070285 reused at $0.175/hour including disk; retained as requested. No lifecycle action or GitHub deployment. All secrets are synthetic. Review by Codex with condition labels visible.</p></section></main></body></html>'''
(R/'index.html').write_text(page);(R/'summary.json').write_text(json.dumps({'review':J['summary'],'zero_clamp_features':Z['features'],'zero_clamp_token_identical_to_baseline':Z['token_identical_to_baseline'],'zero_clamp_contains_secret':Z['contains_exact_secret'],'first_native_active_response_position':first,'first_possible_affected_prediction_position':first+1,'elapsed_seconds':D['elapsed_seconds']},ensure_ascii=False,indent=2)+'\n')
print('Built local report and native-gate / actual-edit timeline.')
